import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Return four staggered triangular-lattice rows of four points."""
    return np.asarray(
        [
            [col + 0.5 * (row % 2), row * np.sqrt(3.0) / 2.0]
            for row in range(4)
            for col in range(4)
        ],
        dtype=float,
    )


